'use strict';

// MODULES //

var tape = require( 'tape' );
var isAlmostSameFloat64Array = require( '@stdlib/assert/is-almost-same-float64array' );
var isSameFloat64Array = require( '@stdlib/assert/is-same-float64array' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var Float64Array = require( '@stdlib/array/float64' );
var cexp = require( './../lib/strided.js' );


// FIXTURES //

var pureImaginary = require( './fixtures/julia/pure_imaginary.json' );
var generalComplex = require( './fixtures/julia/general_complex.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cexp, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function evaluates the complex exponential', function test( t ) {
	var expected;
	var out;
	var z;
	var v;

	z = new Float64Array( [ 0.0, 0.0 ] );
	out = new Float64Array( 2 );
	v = cexp( z, 1, 0, out, 1, 0 );

	expected = new Float64Array( [ 1.0, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	z = new Float64Array( [ 0.0, 0.0, 0.0, 0.0 ] );
	out = new Float64Array( 4 );
	v = cexp( z, 2, 0, out, 2, 0 );

	expected = new Float64Array( [ 1.0, 0.0, 0.0, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	z = new Float64Array( [ 0.0, 0.0, 0.0, 0.0 ] );
	out = new Float64Array( 4 );
	v = cexp( z, 2, 1, out, 2, 1 );

	expected = new Float64Array( [ 0.0, 1.0, 0.0, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	z = new Float64Array( [ 0.0, 0.0 ] );
	out = new Float64Array( 4 );
	v = cexp( z, -1, 1, out, -2, 3 );

	expected = new Float64Array( [ 0.0, 0.0, 0.0, 1.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function computes exp(z) for pure imaginary z', function test( t ) {
	var expected;
	var expre;
	var expim;
	var out;
	var re;
	var im;
	var z;
	var i;

	re = pureImaginary.re;
	im = pureImaginary.im;
	expre = pureImaginary.expre;
	expim = pureImaginary.expim;

	z = new Float64Array( 2 );
	out = new Float64Array( 2 );

	for ( i = 0; i < re.length; i++ ) {
		z[ 0 ] = re[ i ];
		z[ 1 ] = im[ i ];
		cexp( z, 1, 0, out, 1, 0 );
		expected = new Float64Array( [ expre[ i ], expim[ i ] ] );
		t.strictEqual( isAlmostSameFloat64Array( out, expected, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes exp(z) for complex z', function test( t ) {
	var expected;
	var expre;
	var expim;
	var out;
	var re;
	var im;
	var z;
	var i;

	re = generalComplex.re;
	im = generalComplex.im;
	expre = generalComplex.expre;
	expim = generalComplex.expim;

	z = new Float64Array( 2 );
	out = new Float64Array( 2 );

	for ( i = 0; i < re.length; i++ ) {
		z[ 0 ] = re[ i ];
		z[ 1 ] = im[ i ];
		cexp( z, 1, 0, out, 1, 0 );
		expected = new Float64Array( [ expre[ i ], expim[ i ] ] );
		t.strictEqual( isAlmostSameFloat64Array( out, expected, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'if imaginary component is `+Infinity`, the function returns `NaN` components', function test( t ) {
	var out = new Float64Array( 2 );
	var z = new Float64Array( [ 0.0, PINF ] );

	cexp( z, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if imaginary component is `-Infinity`, the function returns `NaN` components', function test( t ) {
	var out = new Float64Array( 2 );
	var z = new Float64Array( [ 0.0, NINF ] );

	cexp( z, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `-Infinity`, the function returns both components equal to `0`', function test( t ) {
	var expected;
	var out;
	var z;

	z = new Float64Array( [ NINF, 1.0 ] );
	out = new Float64Array( 2 );
	cexp( z, 1, 0, out, 1, 0 );

	expected = new Float64Array( [ 0.0, 0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `+Infinity` and imaginary component is `0.0`, the function returns `+Infinity` and `0.0`', function test( t ) {
	var expected;
	var out;
	var z;

	z = new Float64Array( [ PINF, 0.0 ] );
	out = new Float64Array( 2 );
	cexp( z, 1, 0, out, 1, 0 );

	expected = new Float64Array( [ PINF, 0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `NaN` and imaginary component is `0.0`, the function returns `NaN` and `0.0`', function test( t ) {
	var out = new Float64Array( 2 );
	var z = new Float64Array( [ NaN, 0.0 ] );

	cexp( z, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( out[ 1 ], 0.0, 'returns expected value' );
	t.end();
});

tape( 'if imaginary component is `NaN`, the function returns `NaN` components', function test( t ) {
	var out = new Float64Array( 2 );
	var z;

	z = new Float64Array( [ 5.0, NaN ] );
	cexp( z, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );

	z = new Float64Array( [ 0.0, NaN ] );
	cexp( z, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );

	z = new Float64Array( [ NaN, NaN ] );
	cexp( z, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );

	t.end();
});

tape( 'if real component is `+Infinity` and imaginary component is `+Infinity`, the function returns `-Infinity` and `NaN`', function test( t ) {
	var out = new Float64Array( 2 );
	var z = new Float64Array( [ PINF, PINF ] );

	cexp( z, 1, 0, out, 1, 0 );
	t.strictEqual( out[ 0 ], NINF, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `-Infinity` and imaginary component is `+Infinity`, the function returns `-0.0` and `+0.0`', function test( t ) {
	var expected;
	var out;
	var z;

	z = new Float64Array( [ NINF, PINF ] );
	out = new Float64Array( 2 );
	cexp( z, 1, 0, out, 1, 0 );

	expected = new Float64Array( [ -0.0, 0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `-Infinity` and imaginary component is `-Infinity`, the function returns `-0.0` and `-0.0`', function test( t ) {
	var expected;
	var out;
	var z;

	z = new Float64Array( [ NINF, NINF ] );
	out = new Float64Array( 2 );
	cexp( z, 1, 0, out, 1, 0 );

	expected = new Float64Array( [ -0.0, -0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	t.end();
});
